CREATE TABLE IF NOT EXISTS schema_migrations(version VARCHAR(100) PRIMARY KEY,applied_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS users(id CHAR(36) PRIMARY KEY,github_user_id BIGINT NULL UNIQUE,username VARCHAR(100) NOT NULL UNIQUE,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS workspaces(id CHAR(36) PRIMARY KEY,user_id CHAR(36) NOT NULL,name VARCHAR(150) NOT NULL,description TEXT NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_workspaces_user_updated(user_id,updated_at),CONSTRAINT fk_workspaces_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS projects(id CHAR(36) PRIMARY KEY,workspace_id CHAR(36) NULL,user_id CHAR(36) NOT NULL,name VARCHAR(150) NOT NULL,language VARCHAR(50) NOT NULL,repository_owner VARCHAR(100) NULL,repository_name VARCHAR(100) NULL,repository_url VARCHAR(2048) NULL,default_branch VARCHAR(255) NULL,sync_status ENUM('local','clean','ahead','behind','diverged','error') NOT NULL DEFAULT 'local',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_projects_user_updated(user_id,updated_at),CONSTRAINT fk_projects_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,CONSTRAINT fk_projects_workspace FOREIGN KEY(workspace_id) REFERENCES workspaces(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS project_files(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,project_id CHAR(36) NOT NULL,path VARCHAR(1024) NOT NULL,content MEDIUMTEXT NOT NULL,content_sha CHAR(64) NULL,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_project_file_path(project_id,path(255)),CONSTRAINT fk_project_files_project FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS library_items(id VARCHAR(190) PRIMARY KEY,name VARCHAR(200) NOT NULL,category VARCHAR(50) NOT NULL,summary TEXT NOT NULL,source_url VARCHAR(2048) NULL,license_id VARCHAR(100) NULL,metadata JSON NULL,refreshed_at TIMESTAMP NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX idx_library_category_name(category,name));
CREATE TABLE IF NOT EXISTS jobs(id CHAR(36) PRIMARY KEY,user_id CHAR(36) NULL,project_id CHAR(36) NULL,kind ENUM('run','build','test','generation','sync','maintenance') NOT NULL,status ENUM('queued','running','succeeded','failed','cancelled','blocked') NOT NULL DEFAULT 'queued',payload JSON NULL,result JSON NULL,error_message TEXT NULL,started_at TIMESTAMP NULL,finished_at TIMESTAMP NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,expires_at TIMESTAMP NULL,INDEX idx_jobs_status_created(status,created_at),INDEX idx_jobs_expiry(expires_at),CONSTRAINT fk_jobs_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL,CONSTRAINT fk_jobs_project FOREIGN KEY(project_id) REFERENCES projects(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS cron_job_runs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,job_name VARCHAR(100) NOT NULL,status ENUM('started','succeeded','failed','skipped') NOT NULL,details JSON NULL,started_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,finished_at TIMESTAMP NULL,INDEX idx_cron_runs_name_started(job_name,started_at));
CREATE TABLE IF NOT EXISTS audit_events(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id CHAR(36) NULL,event_type VARCHAR(100) NOT NULL,resource_type VARCHAR(100) NULL,resource_id VARCHAR(190) NULL,details JSON NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX idx_audit_created(created_at),CONSTRAINT fk_audit_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);
